#!/usr/bin/env python3
from pathlib import Path
import xml.etree.ElementTree as ET, re, html, shutil, zipfile, sys
from urllib.parse import urlparse, unquote
from bs4 import BeautifulSoup

ROOT=Path(__file__).resolve().parents[1]
XML=ROOT/'data/source.xml'; LOGO=ROOT/'data/logo-groupe.png'; OUT=ROOT/'site'
shutil.rmtree(OUT,ignore_errors=True); OUT.mkdir(parents=True)
NS={'wp':'http://wordpress.org/export/1.2/','content':'http://purl.org/rss/1.0/modules/content/'}
ch=ET.parse(XML).getroot().find('channel')
P={}
for i in ch.findall('item'):
    if i.findtext('wp:post_type',namespaces=NS)=='page' and i.findtext('wp:status',namespaces=NS)=='publish':
        pid=i.findtext('wp:post_id',namespaces=NS); slug=unquote(i.findtext('wp:post_name',namespaces=NS) or pid).lower()
        slug=re.sub(r'[^a-z0-9-]+','-',slug).strip('-') or pid
        P[pid]={'id':pid,'slug':slug,'title':html.unescape(i.findtext('title') or slug),'parent':i.findtext('wp:post_parent',namespaces=NS) or '0','content':i.findtext('content:encoded',namespaces=NS) or ''}
C={}
for p in P.values():C.setdefault(p['parent'],[]).append(p)
for x in C.values():x.sort(key=lambda p:p['title'].lower())
def rid(slug):return next((p['id'] for p in P.values() if p['slug']==slug),None)
def descendants(pid):
    out=set(); q=[pid]
    while q:
        for x in C.get(q.pop(),[]):out.add(x['id']);q.append(x['id'])
    return out
R={s:rid(s) for s in ['roles','savoirs','la-loi-scout','lesprit-des-temps-spirituels','le-village-des-gardiens','imaginaires-que-nous-choisissons','les-rites','progression-louja','progression-scout-et-guide','progression-pionniers-et-caravelles']}
S={k:({v}|descendants(v) if v else set()) for k,v in R.items()}
RITE_SLUGS={'pourquoi-des-ceremonies','la-levee-et-la-descente-du-drapeau','ceremonie-de-lancement-dannee','conseil-dequipe','naissance-de-lequipe','engagement-de-faire-de-son-mieux','investiture-du-panseur','autorisation-de-week-end-en-autonomie'}
def section(p):
    i,s=p['id'],p['slug']
    if i in S['roles'] or s=='panseur':return 'vivre-laventure/roles','roles'
    if i in S['savoirs']:return 'vivre-laventure/savoirs','savoirs'
    if i in S['les-rites'] or s in RITE_SLUGS:return 'vivre-laventure/rites-et-ceremonies','rites'
    if i in S['le-village-des-gardiens']:return 'vivre-laventure/village-des-gardiens','village'
    if i in S['lesprit-des-temps-spirituels'] or s=='le-temps-decoute-de-la-progression-personnelle':return 'grandir-en-paix/temps-spirituels','spiritual'
    if i in S['la-loi-scout'] or s.startswith(('la-guide-','la-jeannette-','la-caravelle-')) or s in {'le-pas-de-recul','les-figures-des-pionniers-caravelles'}:return 'grandir-en-paix/loi-scoute','law'
    if i in S['progression-louja']|S['progression-scout-et-guide']|S['progression-pionniers-et-caravelles']:return 'grandir-en-paix/progression-personnelle','progression'
    if i in S['imaginaires-que-nous-choisissons']:return 'grandir-en-paix/imaginaires','imaginaries'
    if s=='contact':return 'contact','none'
    return 'contenus-originaux','generic'
ROOTMAP={'vivre-laventure/roles':'roles','vivre-laventure/savoirs':'savoirs','vivre-laventure/rites-et-ceremonies':'les-rites','vivre-laventure/village-des-gardiens':'le-village-des-gardiens','grandir-en-paix/temps-spirituels':'lesprit-des-temps-spirituels','grandir-en-paix/loi-scoute':'la-loi-scout','grandir-en-paix/imaginaires':'imaginaires-que-nous-choisissons'}
PATH={}
for p in P.values():
    folder,kind=section(p); root=R.get(ROOTMAP.get(folder,''))
    PATH[p['id']]=folder+'/index.html' if p['id']==root else folder+'/'+p['slug']+'/index.html'
SLUGPATH={p['slug']:PATH[p['id']] for p in P.values()}
def rr(path):return '../'*(len(Path(path).parts)-1)
def leaf(r):return f'<img class="nav-icon" src="{r}assets/logo-feuilles.svg" alt="">'
HEADER='''<div class="foulard"></div><header class="site-header"><div class="wrap navrow"><a class="brand" href="{r}index.html"><img src="{r}assets/logo-embleme.svg" class="brand-emblem" alt=""><img src="{r}assets/logo-groupe.png" class="brand-text" alt="Groupe SGDF de Puisaye"></a><button class="menubtn" aria-label="Ouvrir le menu">☰</button><nav class="menu"><a href="{r}index.html">Accueil</a><div class="navgroup"><a href="{r}vivre-laventure/index.html">{leaf}Vivre l’aventure</a><div class="dropdown"><a href="{r}vivre-laventure/rites-et-ceremonies/index.html">Les rites et cérémonies</a><a href="{r}vivre-laventure/roles/index.html">Les rôles dans l’équipe</a><a href="{r}vivre-laventure/projets/index.html">Les projets</a><a href="{r}vivre-laventure/savoirs/index.html">Les savoirs</a><a href="{r}vivre-laventure/village-des-gardiens/index.html">Le village des gardiens</a></div></div><div class="navgroup"><a href="{r}grandir-en-paix/index.html">{leaf}Grandir en paix</a><div class="dropdown"><a href="{r}grandir-en-paix/temps-spirituels/index.html">L’esprit des temps spirituels</a><a href="{r}grandir-en-paix/loi-scoute/index.html">La Loi scoute</a><a href="{r}grandir-en-paix/progression-personnelle/index.html">La progression personnelle</a><a href="{r}grandir-en-paix/imaginaires/index.html">Les imaginaires</a></div></div><a href="{r}contact/index.html">Contact</a></nav></div></header>'''
