INTRO='''<div id="intro-overlay" class="intro-overlay" hidden><div id="intro-player"></div><button id="intro-skip" type="button">Passer l’introduction</button></div>'''
def rewrite(content,path):
    soup=BeautifulSoup(content,'html.parser')
    for x in soup.select('script,style,form'):x.decompose()
    for a in soup.find_all('a',href=True):
        u=urlparse(a['href']); seg=[x for x in unquote(u.path).split('/') if x]
        if 'scoutsdepuisaye.wordpress.com' in u.netloc and seg:
            slug=re.sub(r'[^a-z0-9-]+','-',seg[-1].lower()).strip('-'); target=SLUGPATH.get(slug)
            if target:a['href']=rr(path)+target
    seen=set();toc=[]
    for h in soup.find_all(['h2','h3']):
        key=re.sub(r'[^a-z0-9]+','-',h.get_text(' ',strip=True).lower()).strip('-') or 'section'; orig=key;n=2
        while key in seen:key=f'{orig}-{n}';n+=1
        seen.add(key);h['id']=key;toc.append((key,h.get_text(' ',strip=True)))
    for im in soup.find_all('img'):im['loading']='lazy'
    return str(soup),toc
def side(title,links,clickable=True):
    if not links:return f'<div class="sidebox"><h2>{title}</h2></div>'
    body=''.join(f'<a href="{h}">{html.escape(t)}</a>' for h,t in links) if clickable else ''.join(f'<span>{html.escape(t)}</span>' for _,t in links)
    return f'<div class="sidebox"><h2>{title}</h2>{body}</div>'
def auto_side(p,path,toc):
    folder,kind=section(p);items=[]
    if kind=='roles':items=C.get(R['roles'],[])+[x for x in P.values() if x['slug']=='panseur']
    elif kind in {'savoirs','rites','law','progression'}:items=C.get(p['id'],[]) or C.get(p['parent'],[])
    if items:return side('Dans cette section',[(rr(path)+PATH[x['id']],x['title']) for x in items if x['id'] in PATH])
    return side('Dans cette page',[('#'+i,t) for i,t in toc]) if toc else ''
def write(path,title,body,aside='',home=False):
    r=rr(path); dst=OUT/path;dst.parent.mkdir(parents=True,exist_ok=True)
    main=body if home else f'<section class="pagehead"><div class="wrap"><h1>{html.escape(title)}</h1></div></section><div class="wrap layout"><article class="content">{body}</article><aside>{aside}</aside></div>'
    dst.write_text(f'<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} | Scouts de Puisaye</title><link rel="stylesheet" href="{r}assets/style.css"></head><body>{INTRO}{HEADER.format(r=r,leaf=leaf(r))}<main>{main}</main>{FOOTER.format(r=r)}<script>window.SITE_ROOT="{r}"</script><script src="{r}assets/site.js"></script></body></html>',encoding='utf-8')
# Import all published pages first
for p in P.values():
    path=PATH[p['id']]; body,toc=rewrite(p['content'],path); write(path,p['title'],body,auto_side(p,path,toc))
