# Branch law pages extracted by title/slug
def branch_laws(prefix):
    out=[]
    for p in P.values():
        if p['slug'].startswith(prefix) and p['id'] in PATH:
            short=re.sub(r'^(La |Le )?(Jeannette,? le Louveteau,?|Guide,? le Scout,?|caravelle,? le pionnier,?)\s*','',p['title'],flags=re.I).strip(' .')
            out.append((rr('grandir-en-paix/progression-personnelle/x/index.html')+PATH[p['id']],short or p['title']))
    return sorted(out,key=lambda x:x[1].lower())
